const serviceAliases: Record<string, string> = {
  "apache-httpd": "apache",
  httpd: "apache",
  postgres: "postgresql",
  pg: "postgresql",
  mongo: "mongodb",
  es: "elasticsearch",
  registry: "docker",
  "docker-registry": "docker",
  k8s: "kubernetes",
  "fluent-bit": "fluentbit",
  "argo-cd": "argocd",
  "apache-kafka": "kafka",
  "apache-tomcat": "tomcat",
  "apache-flink": "flink",
  "apache-spark": "spark",
  "apache-pulsar": "pulsar",
  "apache-rocketmq": "rocketmq",
  "apache-cassandra": "cassandra",
}

export function resolveServiceIcon(name: string): ServiceBrandIcon | null {
  const normalized = name.trim().toLowerCase().replace(/[\s_]+/g, "-")
  const key = serviceAliases[normalized] ?? normalized
  return serviceBrandIcons[key] ?? null
}
